import type { PersonId } from "./Identity.ts";
import type { MembershipRole, TeamId } from "./Team.ts";

/**
 * Who is asking, as the Organization's Durable Object knows them right now (never a token
 * claim): an active Person, whether they are an Organization admin, and their active Memberships.
 */
export interface Actor {
  readonly personId: PersonId;
  readonly organizationAdmin: boolean;
  /** One role per Team, from active Memberships only. An ended Membership grants nothing. */
  readonly roles: ReadonlyMap<TeamId, MembershipRole>;
}

/** Actions on the Organization as a whole. */
export type OrganizationAction =
  | "organization.viewSettings"
  | "organization.updateSettings"
  | "organization.setAdmin"
  | "organization.removePerson"
  | "organization.listTeams"
  | "organization.createTeam";

/** Actions on one Team. */
export type TeamAction =
  | "team.view"
  | "team.update"
  | "team.viewRoster"
  | "team.addMember"
  | "team.removeMember"
  | "team.assignLead"
  | "team.removeLead"
  | "team.viewResults";

export type Action = OrganizationAction | TeamAction;

export type Resource = { readonly _tag: "Organization" } | { readonly _tag: "Team"; readonly teamId: TeamId };

/** Each action takes the resource it is about, so a Team action cannot be asked of the Organization. */
export type ResourceOf<A extends Action> = A extends TeamAction
  ? Extract<Resource, { readonly _tag: "Team" }>
  : Extract<Resource, { readonly _tag: "Organization" }>;

/** Who an action is open to: Organization admins, or a role in the Team the action is about. */
type Grantee = "admin" | MembershipRole;

/**
 * The permission table (SPEC §5.6), the only place permissions are defined. Being an
 * Organization admin covers administration only (ADR 0003): an admin reads a Team's roster
 * because adding, removing, and assigning Leads needs it, but never its Results, which take a
 * Membership in that Team.
 */
export const PERMISSIONS: { readonly [A in Action]: ReadonlyArray<Grantee> } = {
  "organization.viewSettings": ["admin"],
  "organization.updateSettings": ["admin"],
  "organization.setAdmin": ["admin"],
  "organization.removePerson": ["admin"],
  "organization.listTeams": ["admin"],
  "organization.createTeam": ["admin"],
  "team.view": ["admin", "lead", "member", "viewer"],
  "team.update": ["admin"],
  "team.viewRoster": ["admin", "lead"],
  "team.addMember": ["admin", "lead"],
  "team.removeMember": ["admin", "lead"],
  "team.assignLead": ["admin"],
  "team.removeLead": ["admin"],
  "team.viewResults": ["lead", "member", "viewer"],
};

/** Whether `actor` may do `action` to `resource`. */
export const can = <A extends Action>(actor: Actor, action: A, resource: ResourceOf<A>): boolean => {
  const grantees = PERMISSIONS[action];
  if (actor.organizationAdmin && grantees.includes("admin")) return true;
  if (resource._tag !== "Team") return false;
  const role = actor.roles.get(resource.teamId);
  return role !== undefined && grantees.includes(role);
};
import { describe, expect, it } from "@effect/vitest";
import { PersonId } from "./Identity.ts";
import { type Action, type Actor, can, PERMISSIONS, type TeamAction } from "./Permissions.ts";
import { type MembershipRole, TeamId } from "./Team.ts";

const team = TeamId.make("platform");
const otherTeam = TeamId.make("design");

const actor = (organizationAdmin: boolean, role?: MembershipRole): Actor => ({
  personId: PersonId.make("person"),
  organizationAdmin,
  roles: new Map(role === undefined ? [] : [[team, role]]),
});

/** The people the table is about: every role in `team`, an admin with and without a Membership, and outsiders. */
const ACTORS = {
  admin: actor(true),
  adminLead: actor(true, "lead"),
  lead: actor(false, "lead"),
  member: actor(false, "member"),
  viewer: actor(false, "viewer"),
  leadElsewhere: { ...actor(false), roles: new Map([[otherTeam, "lead" as const]]) },
  nobody: actor(false),
} satisfies Record<string, Actor>;
type Who = keyof typeof ACTORS;
const EVERYONE = Object.keys(ACTORS) as ReadonlyArray<Who>;

/**
 * SPEC §5.6: one row per action, listing exactly who may do it (to `team` for Team actions).
 * Everyone not listed is refused. An Organization admin administers but never reads Results
 * (ADR 0003), and a role in another Team grants nothing here.
 */
const TABLE: { readonly [A in Action]: ReadonlyArray<Who> } = {
  "organization.viewSettings": ["admin", "adminLead"],
  "organization.updateSettings": ["admin", "adminLead"],
  "organization.setAdmin": ["admin", "adminLead"],
  "organization.removePerson": ["admin", "adminLead"],
  "organization.listTeams": ["admin", "adminLead"],
  "organization.createTeam": ["admin", "adminLead"],
  "team.view": ["admin", "adminLead", "lead", "member", "viewer"],
  "team.update": ["admin", "adminLead"],
  "team.viewRoster": ["admin", "adminLead", "lead"],
  "team.addMember": ["admin", "adminLead", "lead"],
  "team.removeMember": ["admin", "adminLead", "lead"],
  "team.assignLead": ["admin", "adminLead"],
  "team.removeLead": ["admin", "adminLead"],
  "team.viewResults": ["adminLead", "lead", "member", "viewer"],
};

const isTeamAction = (action: Action): action is TeamAction => action.startsWith("team.");

const ask = (who: Who, action: Action): boolean =>
  can(ACTORS[who], action, isTeamAction(action) ? { _tag: "Team", teamId: team } : { _tag: "Organization" });

const rows = (Object.keys(TABLE) as ReadonlyArray<Action>).flatMap((action) =>
  EVERYONE.map((who) => ({ action, who, allowed: TABLE[action].includes(who) })),
);

describe("the permission table", () => {
  it("covers every action the permission function knows", () => {
    expect(Object.keys(TABLE).sort()).toEqual(Object.keys(PERMISSIONS).sort());
  });

  it.each(rows)("$who → $action: $allowed", ({ who, action, allowed }) => {
    expect(ask(who, action)).toBe(allowed);
  });

  it("never lets an Organization admin without a Membership read a Team's Results", () => {
    expect(can(ACTORS.admin, "team.viewResults", { _tag: "Team", teamId: team })).toBe(false);
    expect(can(ACTORS.admin, "team.viewRoster", { _tag: "Team", teamId: team })).toBe(true);
  });

  it("grants a role only in its own Team", () => {
    expect(can(ACTORS.leadElsewhere, "team.addMember", { _tag: "Team", teamId: otherTeam })).toBe(true);
    expect(can(ACTORS.leadElsewhere, "team.addMember", { _tag: "Team", teamId: team })).toBe(false);
  });
});
export * from "./Identity.ts";
export * from "./Organization.ts";
export * from "./SignIn.ts";
export * from "./SignInFlow.ts";
export * from "./SignInPorts.ts";
export * from "./Directory.ts";
export * from "./Permissions.ts";
export * from "./Team.ts";
export * from "./DirectoryFlow.ts";
export * from "./email/index.ts";
export * from "./people/index.ts";
import { Schema } from "effect";
import { EmailAddress } from "../email/Email.ts";
import { PersonId } from "./Identity.ts";

/** A Team within one Organization. Teams do not nest in Release 1: a Team has no parent. */
export const TeamId = Schema.String.pipe(Schema.brand("TeamId"));
export type TeamId = typeof TeamId.Type;

/** One Membership: a Person's role in one Team over a date range. */
export const MembershipId = Schema.String.pipe(Schema.brand("MembershipId"));
export type MembershipId = typeof MembershipId.Type;

/** A Team's name: trimmed, 1 to 100 characters, unique within its Organization (ignoring case). */
export const TeamName = Schema.String.pipe(
  Schema.check(Schema.isTrimmed(), Schema.isMinLength(1), Schema.isMaxLength(100)),
);

/** IANA names only (`Europe/Berlin`, `UTC`): no offsets like `+01:00`, which Intl also accepts. */
const IANA_SHAPE = /^[A-Za-z][A-Za-z0-9_+-]*(?:\/[A-Za-z0-9_+-]+)*$/;

/** Whether the runtime's time zone database knows this IANA name. */
export const isTimeZone = (name: string): boolean => {
  if (!IANA_SHAPE.test(name)) return false;
  try {
    new Intl.DateTimeFormat("en", { timeZone: name });
    return true;
  } catch {
    return false;
  }
};

/** A Team's time zone, an IANA name. Cadences and answer windows are read in it. */
export const TimeZone = Schema.String.pipe(
  Schema.check(Schema.makeFilter(isTimeZone, { expected: "an IANA time zone name" })),
  Schema.brand("TimeZone"),
);
export type TimeZone = typeof TimeZone.Type;

/**
 * A role in a Team's Membership. Release 1 assigns only `lead` and `member`; `viewer` is part of
 * the model (and of the permission table) so later releases need no migration.
 */
export const MembershipRole = Schema.Literals(["lead", "member", "viewer"]);
export type MembershipRole = typeof MembershipRole.Type;

/** The roles a Lead or admin can give in Release 1. */
export const AssignableRole = Schema.Literals(["lead", "member"]);
export type AssignableRole = typeof AssignableRole.Type;

/**
 * The Organization's minimum group size N (ADR 0004): at least 3, default 4. The cap only keeps
 * typos out. Each Round later stores the N it closed under.
 */
export const MinimumGroupSize = Schema.Int.pipe(
  Schema.check(Schema.isGreaterThanOrEqualTo(3), Schema.isLessThanOrEqualTo(100)),
);
export const DEFAULT_MINIMUM_GROUP_SIZE = 4;

/** A Team as a list shows it, with the caller's own role there (none for an admin outside it). */
export const TeamSummary = Schema.Struct({
  id: TeamId,
  name: Schema.String,
  timeZone: TimeZone,
  yourRole: Schema.NullOr(MembershipRole),
});
export type TeamSummary = typeof TeamSummary.Type;

/** One active Membership in a Team's roster. `since` is when it started (epoch ms). */
export const RosterEntry = Schema.Struct({
  personId: PersonId,
  email: EmailAddress,
  role: MembershipRole,
  since: Schema.Int,
});
export type RosterEntry = typeof RosterEntry.Type;

/** What the caller may do with this Team, so the screen shows only what will work. */
export const TeamAbilities = Schema.Struct({
  update: Schema.Boolean,
  manageLeads: Schema.Boolean,
  manageMembers: Schema.Boolean,
  viewResults: Schema.Boolean,
});
export type TeamAbilities = typeof TeamAbilities.Type;

/** A Team's detail: its active roster. Never Result data (ADR 0003). */
export const TeamDetail = Schema.Struct({
  team: TeamSummary,
  roster: Schema.Array(RosterEntry),
  may: TeamAbilities,
});
export type TeamDetail = typeof TeamDetail.Type;

/** An active Person as the Organization admin's People list shows them. */
export const PersonSummary = Schema.Struct({
  personId: PersonId,
  email: EmailAddress,
  organizationAdmin: Schema.Boolean,
  /** Signed in at least once, so linked to a WorkOS user. */
  linked: Schema.Boolean,
});
export type PersonSummary = typeof PersonSummary.Type;

/** The Organization settings screen: N and the People with their admin flag. */
export const OrganizationSettings = Schema.Struct({
  name: Schema.String,
  minimumGroupSize: MinimumGroupSize,
  people: Schema.Array(PersonSummary),
});
export type OrganizationSettings = typeof OrganizationSettings.Type;

export class TeamNotFound extends Schema.TaggedError<TeamNotFound, { readonly brand: unique symbol }>()(
  "TeamNotFound",
  {},
  { httpApiStatus: 404 },
) {}

/** No such active Person, or not in that Team in the role the request needs. */
export class PersonNotFound extends Schema.TaggedError<PersonNotFound, { readonly brand: unique symbol }>()(
  "PersonNotFound",
  {},
  { httpApiStatus: 404 },
) {}

/** A Team always keeps at least one Lead. Assign another Lead first. */
export class LastLead extends Schema.TaggedError<LastLead, { readonly brand: unique symbol }>()(
  "LastLead",
  { teamId: TeamId },
  { httpApiStatus: 409 },
) {}

/** An Organization always keeps at least one Organization admin. */
export class LastAdmin extends Schema.TaggedError<LastAdmin, { readonly brand: unique symbol }>()(
  "LastAdmin",
  {},
  { httpApiStatus: 409 },
) {}

export class TeamNameTaken extends Schema.TaggedError<TeamNameTaken, { readonly brand: unique symbol }>()(
  "TeamNameTaken",
  {},
  { httpApiStatus: 409 },
) {}
import { Schema } from "effect";

/** Identifies an Organization, the tenant that owns every other record. */
export const OrganizationId = Schema.String.pipe(Schema.brand("OrganizationId"));
export type OrganizationId = typeof OrganizationId.Type;

export class Organization extends Schema.Class<Organization, { readonly brand: unique symbol }>(
  "Organization",
)({
  id: OrganizationId,
  name: Schema.NonEmptyString,
}) {}

/** What a client may supply when creating an Organization. */
export const CreateOrganization = Schema.Struct({
  name: Schema.NonEmptyString,
});
export type CreateOrganization = typeof CreateOrganization.Type;

export class OrganizationNotFound extends Schema.TaggedError<
  OrganizationNotFound,
  { readonly brand: unique symbol }
>()("OrganizationNotFound", {}, { httpApiStatus: 404 }) {}

import { Option } from "effect";
import { EmailAddress, SendId, type TransactionalEmail } from "../email/Email.ts";
import { normaliseEmail, type PersonId, type WorkosUserId } from "./Identity.ts";
import { type Actor, can } from "./Permissions.ts";
import type { OrganizationRole } from "./SignInPorts.ts";
import type {
  AssignableRole,
  MembershipId,
  MembershipRole,
  OrganizationSettings,
  TeamDetail,
  TeamId,
  TeamSummary,
  TimeZone,
} from "./Team.ts";

/**
 * The People, Teams, and Memberships of one Organization, and the rules that change them.
 * Everything here is pure: the Organization Durable Object loads its state, asks `decide`, and
 * applies the changes in one transaction (ADR 0006); the in-memory fakes do the same. Records are
 * plain data (`null`, not `Option`) because they cross the Durable Object's RPC boundary.
 */

export interface PersonRecord {
  readonly id: PersonId;
  readonly email: EmailAddress;
  readonly workosUserId: WorkosUserId | null;
  readonly organizationAdmin: boolean;
  /** When the Person was removed from the Organization (epoch ms). Their history stays. */
  readonly removedAt: number | null;
}

export interface TeamRecord {
  readonly id: TeamId;
  readonly name: string;
  readonly timeZone: TimeZone;
}

export interface MembershipRecord {
  readonly id: MembershipId;
  readonly teamId: TeamId;
  readonly personId: PersonId;
  readonly role: MembershipRole;
  readonly startedAt: number;
  /** When it ended (epoch ms); `null` while active. Ended Memberships are kept as history. */
  readonly endedAt: number | null;
}

export interface DirectoryState {
  readonly organizationName: string;
  readonly minimumGroupSize: number;
  readonly people: ReadonlyArray<PersonRecord>;
  readonly teams: ReadonlyArray<TeamRecord>;
  readonly memberships: ReadonlyArray<MembershipRecord>;
}

/**
 * Someone added by email. The ids are minted by the caller and used only when a new Person or
 * Membership is needed, so `decide` stays pure.
 */
export interface NewMember {
  readonly email: EmailAddress;
  readonly personId: PersonId;
  readonly membershipId: MembershipId;
  /** Where the "You've been added" email sends them. */
  readonly signInUrl: string;
}

export type DirectoryCommand =
  | {
      readonly _tag: "CreateTeam";
      readonly teamId: TeamId;
      readonly name: string;
      readonly timeZone: TimeZone;
      readonly lead: NewMember;
    }
  | {
      readonly _tag: "UpdateTeam";
      readonly teamId: TeamId;
      readonly name: string;
      readonly timeZone: TimeZone;
    }
  /** Adds by email in `role`. `lead` assigns a Lead, promoting a member who is in the Team already. */
  | {
      readonly _tag: "AddMember";
      readonly teamId: TeamId;
      readonly role: AssignableRole;
      readonly member: NewMember;
    }
  /** Ends the Person's Membership in the Team, whatever its role. */
  | { readonly _tag: "RemoveMember"; readonly teamId: TeamId; readonly personId: PersonId }
  /** Ends a Lead's lead Membership; they stay in the Team as a member. */
  | {
      readonly _tag: "RemoveLead";
      readonly teamId: TeamId;
      readonly personId: PersonId;
      readonly membershipId: MembershipId;
    }
  | { readonly _tag: "RemovePerson"; readonly personId: PersonId }
  | { readonly _tag: "SetAdmin"; readonly personId: PersonId; readonly organizationAdmin: boolean }
  | { readonly _tag: "UpdateSettings"; readonly minimumGroupSize: number };

/** A change to the Organization's own data, applied atomically with the others of a decision. */
export type DirectoryChange =
  | { readonly _tag: "PersonAdded"; readonly person: PersonRecord }
  | { readonly _tag: "PersonRestored"; readonly personId: PersonId }
  | { readonly _tag: "PersonRemoved"; readonly personId: PersonId; readonly at: number }
  | { readonly _tag: "AdminSet"; readonly personId: PersonId; readonly organizationAdmin: boolean }
  | { readonly _tag: "TeamAdded"; readonly team: TeamRecord }
  | { readonly _tag: "TeamUpdated"; readonly team: TeamRecord }
  | { readonly _tag: "MembershipStarted"; readonly membership: MembershipRecord }
  | { readonly _tag: "MembershipEnded"; readonly membershipId: MembershipId; readonly at: number }
  | { readonly _tag: "SettingsUpdated"; readonly minimumGroupSize: number }
  /** Creates the send (idempotent per id) in the same transaction, through the send states. */
  | {
      readonly _tag: "EmailRequested";
      readonly sendId: SendId;
      readonly recipient: EmailAddress;
      readonly email: TransactionalEmail;
    };

/** A Person as the global index and WorkOS need to hear about them. */
export interface PersonRef {
  readonly id: PersonId;
  readonly email: EmailAddress;
  readonly workosUserId: WorkosUserId | null;
}

/**
 * What must happen outside the Organization once its changes are committed. Each is idempotent,
 * and repeating the command repeats them, so a crash halfway is mended by a retry.
 */
export type FollowUp =
  /** Keep the D1 `person_index` row (sign-in routing) in step with an active Person. */
  | { readonly _tag: "IndexPerson"; readonly person: PersonRef }
  /** A removed Person is no longer a sign-in candidate. */
  | { readonly _tag: "UnindexPerson"; readonly personId: PersonId }
  /** So AuthKit stops putting the user back into this Organization at sign-in (ADR 0010). */
  | { readonly _tag: "DeactivateWorkosMembership"; readonly userId: WorkosUserId }
  | { readonly _tag: "SetWorkosRole"; readonly userId: WorkosUserId; readonly role: OrganizationRole }
  /** Ask the Queue consumer to deliver the send, if it is still pending. */
  | { readonly _tag: "QueueEmail"; readonly sendId: SendId };

/** Why a command or a view was refused. Plain data; the flow turns it into the API's errors. */
export type DirectoryRejection =
  | { readonly _tag: "Forbidden" }
  | { readonly _tag: "TeamNotFound" }
  | { readonly _tag: "PersonNotFound" }
  | { readonly _tag: "LastLead"; readonly teamId: TeamId }
  | { readonly _tag: "LastAdmin" }
  | { readonly _tag: "TeamNameTaken" };

export type Decision =
  | { readonly _tag: "Rejected"; readonly rejection: DirectoryRejection }
  | {
      readonly _tag: "Accepted";
      readonly changes: ReadonlyArray<DirectoryChange>;
      readonly followUps: ReadonlyArray<FollowUp>;
    };

/** A view, or why it was refused. */
export type Viewed<A> =
  | { readonly _tag: "Viewed"; readonly value: A }
  | { readonly _tag: "Rejected"; readonly rejection: DirectoryRejection };

const reject = (
  rejection: DirectoryRejection,
): { readonly _tag: "Rejected"; readonly rejection: DirectoryRejection } => ({
  _tag: "Rejected",
  rejection,
});
const forbidden = reject({ _tag: "Forbidden" });

const accept = (
  changes: ReadonlyArray<DirectoryChange>,
  followUps: ReadonlyArray<FollowUp> = [],
): Decision => ({
  _tag: "Accepted",
  changes,
  followUps,
});

/** The send id of the "You've been added" email for a Membership: one email per Membership. */
export const addedEmailSendId = (membershipId: MembershipId): SendId => SendId.make(`added-${membershipId}`);

const isActive = (membership: MembershipRecord) => membership.endedAt === null;

const activePeople = (state: DirectoryState) => state.people.filter((person) => person.removedAt === null);

const activeMemberships = (state: DirectoryState, teamId: TeamId) =>
  state.memberships.filter((membership) => membership.teamId === teamId && isActive(membership));

const activeMembershipOf = (state: DirectoryState, teamId: TeamId, personId: PersonId) =>
  activeMemberships(state, teamId).find((membership) => membership.personId === personId);

const leadsOf = (state: DirectoryState, teamId: TeamId) =>
  activeMemberships(state, teamId).filter((membership) => membership.role === "lead");

const findTeam = (state: DirectoryState, teamId: TeamId) => state.teams.find((team) => team.id === teamId);

const refOf = (person: PersonRecord): PersonRef => ({
  id: person.id,
  email: person.email,
  workosUserId: person.workosUserId,
});

/** The actor for an active Person, from this state alone. None for a removed or unknown Person. */
export const actorOf = (state: DirectoryState, personId: PersonId): Option.Option<Actor> => {
  const person = state.people.find((each) => each.id === personId && each.removedAt === null);
  if (person === undefined) return Option.none();
  const roles = new Map<TeamId, MembershipRole>();
  for (const membership of state.memberships) {
    if (membership.personId === personId && isActive(membership))
      roles.set(membership.teamId, membership.role);
  }
  return Option.some({ personId, organizationAdmin: person.organizationAdmin, roles });
};

const nameTaken = (state: DirectoryState, name: string, except?: TeamId) =>
  state.teams.some(
    (team) => team.id !== except && team.name.toLocaleLowerCase("en") === name.toLocaleLowerCase("en"),
  );

/**
 * Puts someone into a Team in `role`: finds their Person by email (restoring a removed one, whose
 * history stays) or creates one with email only (ADR 0002), starts the Membership, and asks for
 * the "You've been added to <Team> by <Lead>" email. Already in the Team in that role (or as Lead
 * when `member` is asked): nothing changes, and the follow-ups run again.
 */
const putInTeam = (
  state: DirectoryState,
  adder: PersonRecord,
  team: TeamRecord,
  role: AssignableRole,
  member: NewMember,
  now: number,
): Decision => {
  const email = EmailAddress.make(normaliseEmail(member.email));
  const existing = state.people.find((person) => person.email === email);
  const person: PersonRecord = existing ?? {
    id: member.personId,
    email,
    workosUserId: null,
    organizationAdmin: false,
    removedAt: null,
  };
  const changes: Array<DirectoryChange> = [];
  if (existing === undefined) changes.push({ _tag: "PersonAdded", person });
  else if (existing.removedAt !== null) changes.push({ _tag: "PersonRestored", personId: existing.id });

  const index: FollowUp = { _tag: "IndexPerson", person: refOf(person) };
  const current = existing === undefined ? undefined : activeMembershipOf(state, team.id, existing.id);
  if (current !== undefined && (current.role === role || current.role === "lead")) {
    return accept(changes, [index, { _tag: "QueueEmail", sendId: addedEmailSendId(current.id) }]);
  }

  const membership: MembershipRecord = {
    id: member.membershipId,
    teamId: team.id,
    personId: person.id,
    role,
    startedAt: now,
    endedAt: null,
  };
  if (current !== undefined) {
    // A member made Lead: one role per Membership, so the member one ends and a lead one starts.
    changes.push({ _tag: "MembershipEnded", membershipId: current.id, at: now });
    changes.push({ _tag: "MembershipStarted", membership });
    return accept(changes, [index]);
  }
  const sendId = addedEmailSendId(membership.id);
  changes.push(
    { _tag: "MembershipStarted", membership },
    {
      _tag: "EmailRequested",
      sendId,
      recipient: person.email,
      email: { _tag: "AddedToTeam", teamName: team.name, leadName: adder.email, signInUrl: member.signInUrl },
    },
  );
  return accept(changes, [index, { _tag: "QueueEmail", sendId }]);
};

/**
 * Decides one command by `actorId`, from the Organization's current state. The permission table
 * is asked first, so a refusal never says whether a Team or Person exists to someone who may not
 * know. Then the rules: a Team always keeps a Lead, the Organization always keeps an admin, and
 * removing someone ends Memberships on that date but never deletes a Person or their history.
 */
export const decide = (
  state: DirectoryState,
  actorId: PersonId,
  command: DirectoryCommand,
  now: number,
): Decision => {
  const actor = actorOf(state, actorId);
  const adder = state.people.find((person) => person.id === actorId);
  if (Option.isNone(actor) || adder === undefined) return forbidden;
  const allowed = actor.value;
  const organization = { _tag: "Organization" } as const;

  switch (command._tag) {
    case "CreateTeam": {
      if (!can(allowed, "organization.createTeam", organization)) return forbidden;
      if (nameTaken(state, command.name)) return reject({ _tag: "TeamNameTaken" });
      const team: TeamRecord = { id: command.teamId, name: command.name, timeZone: command.timeZone };
      if (findTeam(state, team.id) !== undefined) return reject({ _tag: "TeamNameTaken" });
      const withTeam: DirectoryState = { ...state, teams: [...state.teams, team] };
      const lead = putInTeam(withTeam, adder, team, "lead", command.lead, now);
      if (lead._tag === "Rejected") return lead;
      return accept([{ _tag: "TeamAdded", team }, ...lead.changes], lead.followUps);
    }

    case "UpdateTeam": {
      if (!can(allowed, "team.update", { _tag: "Team", teamId: command.teamId })) return forbidden;
      if (findTeam(state, command.teamId) === undefined) return reject({ _tag: "TeamNotFound" });
      if (nameTaken(state, command.name, command.teamId)) return reject({ _tag: "TeamNameTaken" });
      return accept([
        { _tag: "TeamUpdated", team: { id: command.teamId, name: command.name, timeZone: command.timeZone } },
      ]);
    }

    case "AddMember": {
      const action = command.role === "lead" ? "team.assignLead" : "team.addMember";
      if (!can(allowed, action, { _tag: "Team", teamId: command.teamId })) return forbidden;
      const team = findTeam(state, command.teamId);
      if (team === undefined) return reject({ _tag: "TeamNotFound" });
      return putInTeam(state, adder, team, command.role, command.member, now);
    }

    case "RemoveMember": {
      const resource = { _tag: "Team", teamId: command.teamId } as const;
      if (!can(allowed, "team.removeMember", resource)) return forbidden;
      if (findTeam(state, command.teamId) === undefined) return reject({ _tag: "TeamNotFound" });
      const membership = activeMembershipOf(state, command.teamId, command.personId);
      if (membership === undefined) return reject({ _tag: "PersonNotFound" });
      if (membership.role === "lead") {
        // Taking a Lead out of a Team is a Lead change, which only an admin makes.
        if (!can(allowed, "team.removeLead", resource)) return forbidden;
        if (leadsOf(state, command.teamId).length <= 1)
          return reject({ _tag: "LastLead", teamId: command.teamId });
      }
      return accept([{ _tag: "MembershipEnded", membershipId: membership.id, at: now }]);
    }

    case "RemoveLead": {
      if (!can(allowed, "team.removeLead", { _tag: "Team", teamId: command.teamId })) return forbidden;
      if (findTeam(state, command.teamId) === undefined) return reject({ _tag: "TeamNotFound" });
      const membership = activeMembershipOf(state, command.teamId, command.personId);
      if (membership?.role !== "lead") return reject({ _tag: "PersonNotFound" });
      if (leadsOf(state, command.teamId).length <= 1)
        return reject({ _tag: "LastLead", teamId: command.teamId });
      return accept([
        { _tag: "MembershipEnded", membershipId: membership.id, at: now },
        {
          _tag: "MembershipStarted",
          membership: {
            id: command.membershipId,
            teamId: command.teamId,
            personId: command.personId,
            role: "member",
            startedAt: now,
            endedAt: null,
          },
        },
      ]);
    }

    case "RemovePerson": {
      if (!can(allowed, "organization.removePerson", organization)) return forbidden;
      const person = state.people.find((each) => each.id === command.personId);
      if (person === undefined) return reject({ _tag: "PersonNotFound" });
      const followUps: Array<FollowUp> = [{ _tag: "UnindexPerson", personId: person.id }];
      if (person.workosUserId !== null) {
        followUps.push({ _tag: "DeactivateWorkosMembership", userId: person.workosUserId });
      }
      // Removed already: nothing changes here, but the index and WorkOS are put in step again.
      if (person.removedAt !== null) return accept([], followUps);

      const memberships = state.memberships.filter(
        (membership) => membership.personId === person.id && isActive(membership),
      );
      for (const membership of memberships) {
        if (membership.role === "lead" && leadsOf(state, membership.teamId).length <= 1) {
          return reject({ _tag: "LastLead", teamId: membership.teamId });
        }
      }
      if (
        person.organizationAdmin &&
        activePeople(state).filter((each) => each.organizationAdmin).length <= 1
      ) {
        return reject({ _tag: "LastAdmin" });
      }
      const changes: Array<DirectoryChange> = memberships.map((membership) => ({
        _tag: "MembershipEnded",
        membershipId: membership.id,
        at: now,
      }));
      // A Person added back later starts as a plain member, never as the admin they were.
      if (person.organizationAdmin)
        changes.push({ _tag: "AdminSet", personId: person.id, organizationAdmin: false });
      changes.push({ _tag: "PersonRemoved", personId: person.id, at: now });
      return accept(changes, followUps);
    }

    case "SetAdmin": {
      if (!can(allowed, "organization.setAdmin", organization)) return forbidden;
      const person = activePeople(state).find((each) => each.id === command.personId);
      if (person === undefined) return reject({ _tag: "PersonNotFound" });
      if (
        person.organizationAdmin &&
        !command.organizationAdmin &&
        activePeople(state).filter((each) => each.organizationAdmin).length <= 1
      ) {
        return reject({ _tag: "LastAdmin" });
      }
      const followUps: ReadonlyArray<FollowUp> =
        person.workosUserId === null
          ? []
          : [
              {
                _tag: "SetWorkosRole",
                userId: person.workosUserId,
                role: command.organizationAdmin ? "admin" : "member",
              },
            ];
      if (person.organizationAdmin === command.organizationAdmin) return accept([], followUps);
      return accept(
        [{ _tag: "AdminSet", personId: person.id, organizationAdmin: command.organizationAdmin }],
        followUps,
      );
    }

    case "UpdateSettings": {
      if (!can(allowed, "organization.updateSettings", organization)) return forbidden;
      return accept([{ _tag: "SettingsUpdated", minimumGroupSize: command.minimumGroupSize }]);
    }
  }
};

/** Applies a decision's changes to an in-memory state: what the Durable Object does in SQL. */
export const applyChanges = (
  state: DirectoryState,
  changes: ReadonlyArray<DirectoryChange>,
): DirectoryState =>
  changes.reduce<DirectoryState>((current, change) => {
    const updatePerson = (personId: PersonId, update: (person: PersonRecord) => PersonRecord) => ({
      ...current,
      people: current.people.map((person) => (person.id === personId ? update(person) : person)),
    });
    switch (change._tag) {
      case "PersonAdded":
        return { ...current, people: [...current.people, change.person] };
      case "PersonRestored":
        return updatePerson(change.personId, (person) => ({ ...person, removedAt: null }));
      case "PersonRemoved":
        return updatePerson(change.personId, (person) => ({ ...person, removedAt: change.at }));
      case "AdminSet":
        return updatePerson(change.personId, (person) => ({
          ...person,
          organizationAdmin: change.organizationAdmin,
        }));
      case "TeamAdded":
        return { ...current, teams: [...current.teams, change.team] };
      case "TeamUpdated":
        return {
          ...current,
          teams: current.teams.map((team) => (team.id === change.team.id ? change.team : team)),
        };
      case "MembershipStarted":
        return { ...current, memberships: [...current.memberships, change.membership] };
      case "MembershipEnded":
        return {
          ...current,
          memberships: current.memberships.map((membership) =>
            membership.id === change.membershipId ? { ...membership, endedAt: change.at } : membership,
          ),
        };
      case "SettingsUpdated":
        return { ...current, minimumGroupSize: change.minimumGroupSize };
      case "EmailRequested":
        return current;
    }
  }, state);

const summaryOf = (team: TeamRecord, actor: Actor): TeamSummary => ({
  id: team.id,
  name: team.name,
  timeZone: team.timeZone,
  yourRole: actor.roles.get(team.id) ?? null,
});

const byName = (a: { readonly name: string }, b: { readonly name: string }) =>
  a.name.localeCompare(b.name, "en");

/** The Teams the actor sees: every Team for an admin, otherwise the Teams they are in. */
export const teamsView = (state: DirectoryState, actorId: PersonId): Viewed<ReadonlyArray<TeamSummary>> => {
  const actor = actorOf(state, actorId);
  if (Option.isNone(actor)) return forbidden;
  const listAll = can(actor.value, "organization.listTeams", { _tag: "Organization" });
  const teams = state.teams.filter(
    (team) => listAll || can(actor.value, "team.view", { _tag: "Team", teamId: team.id }),
  );
  return { _tag: "Viewed", value: [...teams].sort(byName).map((team) => summaryOf(team, actor.value)) };
};

const ROLE_ORDER: Readonly<Record<MembershipRole, number>> = { lead: 0, member: 1, viewer: 2 };

/** A Team's roster, for its Leads and for Organization admins (who need it to administer it). */
export const teamView = (state: DirectoryState, actorId: PersonId, teamId: TeamId): Viewed<TeamDetail> => {
  const actor = actorOf(state, actorId);
  if (Option.isNone(actor)) return forbidden;
  const resource = { _tag: "Team", teamId } as const;
  if (!can(actor.value, "team.viewRoster", resource)) return forbidden;
  const team = findTeam(state, teamId);
  if (team === undefined) return reject({ _tag: "TeamNotFound" });
  const emails = new Map(state.people.map((person) => [person.id, person.email]));
  const roster = activeMemberships(state, teamId)
    .flatMap((membership) => {
      const email = emails.get(membership.personId);
      return email === undefined
        ? []
        : [{ personId: membership.personId, email, role: membership.role, since: membership.startedAt }];
    })
    .sort((a, b) => ROLE_ORDER[a.role] - ROLE_ORDER[b.role] || a.email.localeCompare(b.email, "en"));
  return {
    _tag: "Viewed",
    value: {
      team: summaryOf(team, actor.value),
      roster,
      may: {
        update: can(actor.value, "team.update", resource),
        manageLeads: can(actor.value, "team.assignLead", resource),
        manageMembers: can(actor.value, "team.addMember", resource),
        viewResults: can(actor.value, "team.viewResults", resource),
      },
    },
  };
};

/** The Organization settings: N, and the active People with their admin flag. Admins only. */
export const settingsView = (state: DirectoryState, actorId: PersonId): Viewed<OrganizationSettings> => {
  const actor = actorOf(state, actorId);
  if (Option.isNone(actor)) return forbidden;
  if (!can(actor.value, "organization.viewSettings", { _tag: "Organization" })) return forbidden;
  return {
    _tag: "Viewed",
    value: {
      name: state.organizationName,
      minimumGroupSize: state.minimumGroupSize,
      people: activePeople(state)
        .map((person) => ({
          personId: person.id,
          email: person.email,
          organizationAdmin: person.organizationAdmin,
          linked: person.workosUserId !== null,
        }))
        .sort((a, b) => a.email.localeCompare(b.email, "en")),
    },
  };
};

import { Clock, Context, Effect, Option } from "effect";
import type { SendId } from "../email/Email.ts";
import type { DirectoryCommand, DirectoryRejection, FollowUp, Viewed } from "./Directory.ts";
import type { PersonId } from "./Identity.ts";
import type { OrganizationId } from "./Organization.ts";
import { Forbidden } from "./SignIn.ts";
import type { Member } from "./SignInFlow.ts";
import { IdentityProvider, PeopleIndex } from "./SignInPorts.ts";
import {
  LastAdmin,
  LastLead,
  type OrganizationSettings,
  PersonNotFound,
  type TeamDetail,
  type TeamId,
  TeamNameTaken,
  TeamNotFound,
  type TeamSummary,
} from "./Team.ts";

/** What the Organization's Durable Object answers to a command once it has committed it, or why not. */
export type CommandResult =
  | { readonly _tag: "Rejected"; readonly rejection: DirectoryRejection }
  /** The follow-ups to run, with `QueueEmail` only for sends that are still pending. */
  | { readonly _tag: "Accepted"; readonly followUps: ReadonlyArray<FollowUp> };

/**
 * The People, Teams, and Memberships of each Organization, as its Durable Object holds them
 * (ADR 0006). Every call authorizes the actor from that object's own data, in the same
 * transaction as the change, so a removed Person or an ended Membership is refused at once.
 */
export interface OrganizationDirectoryShape {
  readonly run: (
    organizationId: OrganizationId,
    actorId: PersonId,
    command: DirectoryCommand,
    now: number,
  ) => Effect.Effect<CommandResult>;
  readonly teams: (
    organizationId: OrganizationId,
    actorId: PersonId,
  ) => Effect.Effect<Viewed<ReadonlyArray<TeamSummary>>>;
  readonly team: (
    organizationId: OrganizationId,
    actorId: PersonId,
    teamId: TeamId,
  ) => Effect.Effect<Viewed<TeamDetail>>;
  readonly settings: (
    organizationId: OrganizationId,
    actorId: PersonId,
  ) => Effect.Effect<Viewed<OrganizationSettings>>;
}

export class OrganizationDirectory extends Context.Service<
  OrganizationDirectory,
  OrganizationDirectoryShape
>()("@surveybeat/domain/OrganizationDirectory") {}

/** Hands a pending send to the email Queue consumer. Delivery is idempotent per send, so repeats are safe. */
export class EmailOutbox extends Context.Service<
  EmailOutbox,
  { readonly queue: (organizationId: OrganizationId, sendId: SendId) => Effect.Effect<void> }
>()("@surveybeat/domain/EmailOutbox") {}

export type DirectoryError = Forbidden | TeamNotFound | PersonNotFound | LastLead | LastAdmin | TeamNameTaken;

const fail = (rejection: DirectoryRejection): Effect.Effect<never, DirectoryError> => {
  switch (rejection._tag) {
    case "Forbidden":
      return Effect.fail(new Forbidden());
    case "TeamNotFound":
      return Effect.fail(new TeamNotFound());
    case "PersonNotFound":
      return Effect.fail(new PersonNotFound());
    case "LastLead":
      return Effect.fail(new LastLead({ teamId: rejection.teamId }));
    case "LastAdmin":
      return Effect.fail(new LastAdmin());
    case "TeamNameTaken":
      return Effect.fail(new TeamNameTaken());
  }
};

const viewed = <A>(view: Viewed<A>): Effect.Effect<A, DirectoryError> =>
  view._tag === "Viewed" ? Effect.succeed(view.value) : fail(view.rejection);

/** Runs one follow-up. Each is idempotent, and a failure leaves the rest for the retry to do. */
const followUp = Effect.fnUntraced(function* (organizationId: OrganizationId, step: FollowUp) {
  const index = yield* PeopleIndex;
  const identityProvider = yield* IdentityProvider;
  const workosOrganization = index.workosOrganizationOf(organizationId);
  switch (step._tag) {
    case "IndexPerson":
      return yield* index.putPerson({
        organizationId,
        personId: step.person.id,
        email: step.person.email,
        userId: Option.fromNullishOr(step.person.workosUserId),
      });
    case "UnindexPerson":
      return yield* index.removePerson(organizationId, step.personId);
    case "DeactivateWorkosMembership": {
      const workos = yield* workosOrganization;
      if (Option.isSome(workos)) yield* identityProvider.deactivateMembership(step.userId, workos.value);
      return;
    }
    case "SetWorkosRole": {
      const workos = yield* workosOrganization;
      if (Option.isSome(workos))
        yield* identityProvider.setMembershipRole(step.userId, workos.value, step.role);
      return;
    }
    case "QueueEmail":
      return yield* (yield* EmailOutbox).queue(organizationId, step.sendId);
  }
});

/**
 * Runs a command as the signed-in Person: the Durable Object authorizes and commits it, then the
 * global index, WorkOS, and the email queue are put in step. Removal reaches WorkOS last, after
 * the Durable Object (which the per-request check asks) and the index already refuse the Person.
 * When WorkOS cannot be reached this fails `AuthUnavailable`; repeating the request finishes it.
 */
export const runDirectoryCommand = Effect.fnUntraced(function* (member: Member, command: DirectoryCommand) {
  const directory = yield* OrganizationDirectory;
  const organizationId = member.organization.id;
  const result = yield* directory.run(
    organizationId,
    member.personId,
    command,
    yield* Clock.currentTimeMillis,
  );
  if (result._tag === "Rejected") return yield* fail(result.rejection);
  for (const step of result.followUps) yield* followUp(organizationId, step);
});

export const viewTeams = (member: Member) =>
  Effect.flatMap(OrganizationDirectory, (directory) =>
    Effect.flatMap(directory.teams(member.organization.id, member.personId), viewed),
  );

export const viewTeam = (member: Member, teamId: TeamId) =>
  Effect.flatMap(OrganizationDirectory, (directory) =>
    Effect.flatMap(directory.team(member.organization.id, member.personId, teamId), viewed),
  );

export const viewSettings = (member: Member) =>
  Effect.flatMap(OrganizationDirectory, (directory) =>
    Effect.flatMap(directory.settings(member.organization.id, member.personId), viewed),
  );
import * as Cloudflare from "@alchemy.run/cloudflare";
import { SqliteClient } from "@effect/sql-sqlite-do";
import {
  type CommandResult,
  decide,
  defaultSendPolicy,
  type DeliveryEventKind,
  type DirectoryCommand,
  type EmailAddress,
  type FollowUp,
  makeSendStore,
  type PersonId,
  type SendId,
  type SendOutcome,
  settingsView,
  type TeamId,
  teamsView,
  teamView,
  type TransactionalEmail,
} from "@surveybeat/domain";
import * as Effect from "effect/Effect";
import * as Option from "effect/Option";
import * as Reactivity from "effect/reactivity/Reactivity";
import * as Scope from "effect/Scope";
import { makeSqlDirectory } from "./SqlDirectory.ts";
import { makeSqlSendRepository } from "./SqlSendRepository.ts";

/**
 * Relative to the directory Alchemy runs in, which is the repository root (`pnpm infra:deploy`, `pnpm test`).
 * It must be a literal: the same expression runs again inside the bundle, where `import.meta.url` differs.
 */
const migrationsDirectory = "packages/cloudflare/migrations";

/**
 * The Organization Durable Object (ADR 0006): one object per Organization, SQLite storage.
 * Methods return plain data (no `Option`), because they cross the RPC boundary.
 * The Main Worker maps it to the domain schemas.
 */
export default class Organization extends Cloudflare.DurableObject<Organization>()(
  "Organization",
  Effect.gen(function* () {
    // Outer phase: capture the SQL files into the bundle.
    const migrations = yield* Cloudflare.SqlMigrations(migrationsDirectory);

    // Inner phase: runs once per object activation, before any method is exposed.
    return Effect.gen(function* () {
      const state = yield* Cloudflare.DurableObjectState;

      // Pass `storage` (not just `db`) so `withTransaction` uses `storage.transaction()`.
      const scope = yield* Scope.make();
      const sql = yield* SqliteClient.make({ storage: state.raw.storage }).pipe(
        Effect.provideService(Scope.Scope, scope),
        Effect.provide(Reactivity.layer),
      );

      yield* migrations.apply().pipe(Effect.orDie);

      // Transactional email: the domain's SendStore on this object's `email_send` table.
      const sends = makeSendStore(makeSqlSendRepository(sql), defaultSendPolicy);
      // People, Teams, and Memberships: the domain decides, this object loads and applies.
      const directory = makeSqlDirectory(sql, sends);

      /** Only sends still waiting go back to the queue; one already sent or failed stays as it is. */
      const pendingOnly = (followUps: ReadonlyArray<FollowUp>) =>
        Effect.filter(followUps, (step) =>
          step._tag === "QueueEmail"
            ? sends
                .get(step.sendId)
                .pipe(Effect.map((record) => record._tag === "Some" && record.value.state._tag === "Pending"))
            : Effect.succeed(true),
        );

      return {
        create: (id: string, name: string) =>
          sql
            .withTransaction(sql`INSERT INTO organization (id, name) VALUES (${id}, ${name})`)
            .pipe(Effect.as({ id, name }), Effect.orDie),

        /** Idempotent: the Organization and its creator as its first Person (an Organization admin in WorkOS). */
        createWithAdmin: (id: string, name: string, personId: string, email: string, workosUserId: string) =>
          sql
            .withTransaction(
              Effect.all([
                sql`INSERT INTO organization (id, name) VALUES (${id}, ${name}) ON CONFLICT (id) DO NOTHING`,
                sql`INSERT INTO person (id, email, workos_user_id, organization_admin)
                    VALUES (${personId}, ${email}, ${workosUserId}, 1)
                    ON CONFLICT (id) DO NOTHING`,
              ]),
            )
            .pipe(Effect.asVoid, Effect.orDie),

        /**
         * Links a Person to a WorkOS user: only an active Person with exactly this (normalised)
         * email, not linked to someone else, and only if the user has no other Person here.
         */
        linkPerson: (personId: string, workosUserId: string, email: string) =>
          sql
            .withTransaction(
              Effect.gen(function* () {
                const other = yield* sql<{ id: string }>`
                  SELECT id FROM person WHERE workos_user_id = ${workosUserId} AND id <> ${personId}`;
                if (other.length > 0) return false;
                yield* sql`
                  UPDATE person SET workos_user_id = ${workosUserId}
                   WHERE id = ${personId} AND email = ${email} AND removed_at IS NULL AND workos_user_id IS NULL`;
                const linked = yield* sql<{ id: string }>`
                  SELECT id FROM person
                   WHERE id = ${personId} AND workos_user_id = ${workosUserId} AND removed_at IS NULL`;
                return linked.length > 0;
              }),
            )
            .pipe(Effect.orDie),

        /** The per-request check: the user's Person here, unless removed, and whether they are an admin. */
        activePerson: (workosUserId: string) =>
          sql<{ id: string; organization_admin: number }>`
            SELECT id, organization_admin FROM person
             WHERE workos_user_id = ${workosUserId} AND removed_at IS NULL`.pipe(
            Effect.map((rows) => {
              const row = rows[0];
              return row === undefined
                ? null
                : { id: row.id, organizationAdmin: row.organization_admin === 1 };
            }),
            Effect.orDie,
          ),

        /**
         * One directory command by `actorId`: authorized from this object's data and applied in the
         * same transaction, so nothing can change in between.
         */
        runDirectoryCommand: (actorId: PersonId, command: DirectoryCommand, now: number) =>
          sql
            .withTransaction(
              Effect.gen(function* () {
                const decision = decide(yield* directory.load, actorId, command, now);
                if (decision._tag === "Rejected") return decision satisfies CommandResult;
                yield* directory.apply(decision.changes);
                return {
                  _tag: "Accepted",
                  followUps: yield* pendingOnly(decision.followUps),
                } satisfies CommandResult;
              }),
            )
            .pipe(Effect.orDie),
        viewTeams: (actorId: PersonId) =>
          directory.load.pipe(Effect.map((state) => teamsView(state, actorId))),
        viewTeam: (actorId: PersonId, teamId: TeamId) =>
          directory.load.pipe(Effect.map((state) => teamView(state, actorId, teamId))),
        viewSettings: (actorId: PersonId) =>
          directory.load.pipe(Effect.map((state) => settingsView(state, actorId))),

        get: (id: string) =>
          sql<{ id: string; name: string }>`SELECT id, name FROM organization WHERE id = ${id}`.pipe(
            Effect.map((rows) => rows[0] ?? null),
            Effect.orDie,
          ),

        createEmailSend: (id: SendId, recipient: EmailAddress, email: TransactionalEmail) =>
          sends.create(id, recipient, email),
        getEmailSend: (id: SendId) => sends.get(id).pipe(Effect.map(Option.getOrNull)),
        claimEmailSend: (id: SendId, now: number) => sends.claim(id, now),
        settleEmailSend: (id: SendId, attempt: number, outcome: SendOutcome, now: number) =>
          sends.settle(id, attempt, outcome, now).pipe(Effect.map(Option.getOrNull)),
        abandonEmailSend: (id: SendId, now: number) =>
          sends.abandon(id, now).pipe(Effect.map(Option.getOrNull)),
        recordEmailDeliveryEvent: (id: SendId, kind: DeliveryEventKind, code: string | null, now: number) =>
          sends.recordDeliveryEvent(id, kind, code, now).pipe(Effect.map(Option.getOrNull)),
      };
    });
  }),
) {}
import type { SqliteClient } from "@effect/sql-sqlite-do";
import {
  DEFAULT_MINIMUM_GROUP_SIZE,
  type DirectoryChange,
  type DirectoryState,
  EmailAddress,
  MembershipId,
  MembershipRole,
  PersonId,
  type SendStoreShape,
  TeamId,
  TimeZone,
  WorkosUserId,
} from "@surveybeat/domain";
import * as Effect from "effect/Effect";
import * as Schema from "effect/Schema";

const OrganizationRow = Schema.Struct({ name: Schema.String, minimum_group_size: Schema.Int });
const PersonRow = Schema.Struct({
  id: PersonId,
  email: EmailAddress,
  workos_user_id: Schema.NullOr(WorkosUserId),
  organization_admin: Schema.Int,
  removed_at: Schema.NullOr(Schema.Int),
});
const TeamRow = Schema.Struct({ id: TeamId, name: Schema.String, time_zone: TimeZone });
const MembershipRow = Schema.Struct({
  id: MembershipId,
  team_id: TeamId,
  person_id: PersonId,
  role: MembershipRole,
  started_at: Schema.Int,
  ended_at: Schema.NullOr(Schema.Int),
});

const rows = <S extends Schema.Top & { readonly DecodingServices: never }>(schema: S) =>
  Schema.decodeUnknownEffect(Schema.Array(schema));

/**
 * The directory tables of the Organization Durable Object (`migrations/0004_teams.sql`): the
 * whole state for `decide`, and the SQL for each change it returns. Run both inside one
 * transaction. A row that does not decode is a defect.
 */
export const makeSqlDirectory = (sql: SqliteClient.SqliteClient, sends: SendStoreShape) => {
  const load: Effect.Effect<DirectoryState> = Effect.gen(function* () {
    const [organization] = yield* sql`SELECT name, minimum_group_size FROM organization LIMIT 1`.pipe(
      Effect.flatMap(rows(OrganizationRow)),
    );
    const people =
      yield* sql`SELECT id, email, workos_user_id, organization_admin, removed_at FROM person`.pipe(
        Effect.flatMap(rows(PersonRow)),
      );
    const teams = yield* sql`SELECT id, name, time_zone FROM team`.pipe(Effect.flatMap(rows(TeamRow)));
    const memberships = yield* sql`
      SELECT id, team_id, person_id, role, started_at, ended_at FROM membership ORDER BY started_at, id`.pipe(
      Effect.flatMap(rows(MembershipRow)),
    );
    return {
      organizationName: organization?.name ?? "",
      minimumGroupSize: organization?.minimum_group_size ?? DEFAULT_MINIMUM_GROUP_SIZE,
      people: people.map((row) => ({
        id: row.id,
        email: row.email,
        workosUserId: row.workos_user_id,
        organizationAdmin: row.organization_admin === 1,
        removedAt: row.removed_at,
      })),
      teams: teams.map((row) => ({ id: row.id, name: row.name, timeZone: row.time_zone })),
      memberships: memberships.map((row) => ({
        id: row.id,
        teamId: row.team_id,
        personId: row.person_id,
        role: row.role,
        startedAt: row.started_at,
        endedAt: row.ended_at,
      })),
    } satisfies DirectoryState;
  }).pipe(Effect.orDie);

  const applyOne = (change: DirectoryChange): Effect.Effect<unknown, unknown> => {
    switch (change._tag) {
      case "PersonAdded": {
        const { person } = change;
        return sql`INSERT INTO person (id, email, workos_user_id, organization_admin, removed_at)
          VALUES (${person.id}, ${person.email}, ${person.workosUserId}, ${person.organizationAdmin ? 1 : 0},
                  ${person.removedAt})`;
      }
      case "PersonRestored":
        return sql`UPDATE person SET removed_at = NULL WHERE id = ${change.personId}`;
      case "PersonRemoved":
        return sql`UPDATE person SET removed_at = ${change.at} WHERE id = ${change.personId}`;
      case "AdminSet":
        return sql`UPDATE person SET organization_admin = ${change.organizationAdmin ? 1 : 0}
          WHERE id = ${change.personId}`;
      case "TeamAdded":
        return sql`INSERT INTO team (id, name, time_zone)
          VALUES (${change.team.id}, ${change.team.name}, ${change.team.timeZone})`;
      case "TeamUpdated":
        return sql`UPDATE team SET name = ${change.team.name}, time_zone = ${change.team.timeZone}
          WHERE id = ${change.team.id}`;
      case "MembershipStarted": {
        const { membership } = change;
        return sql`INSERT INTO membership (id, team_id, person_id, role, started_at, ended_at)
          VALUES (${membership.id}, ${membership.teamId}, ${membership.personId}, ${membership.role},
                  ${membership.startedAt}, ${membership.endedAt})`;
      }
      case "MembershipEnded":
        return sql`UPDATE membership SET ended_at = ${change.at} WHERE id = ${change.membershipId}`;
      case "SettingsUpdated":
        return sql`UPDATE organization SET minimum_group_size = ${change.minimumGroupSize}`;
      case "EmailRequested":
        return sends.create(change.sendId, change.recipient, change.email);
    }
  };

  const apply = (changes: ReadonlyArray<DirectoryChange>): Effect.Effect<void> =>
    Effect.forEach(changes, applyOne, { discard: true }).pipe(Effect.orDie);

  return { load, apply };
};
-- Teams, Memberships, Organization admins, and the minimum group size (slice 04, ADR 0002–0004).

-- The Durable Object, not a token claim, decides who is an Organization admin (ADR 0010); the
-- WorkOS `admin` role is kept in step. Until now the only Person was each Organization's creator,
-- made its admin, so every existing Person is one.
ALTER TABLE person ADD COLUMN organization_admin INTEGER NOT NULL DEFAULT 0 CHECK (organization_admin IN (0, 1));
UPDATE person SET organization_admin = 1;
-- One Person per email: adding an email that has a Person reuses (or restores) it.
CREATE UNIQUE INDEX person_email ON person (email);

-- N, at least 3 (ADR 0004). Each Round will store the N it closed under.
ALTER TABLE organization ADD COLUMN minimum_group_size INTEGER NOT NULL DEFAULT 4 CHECK (minimum_group_size >= 3);

-- Teams do not nest in Release 1: no parent. `time_zone` is an IANA name, checked by the domain.
CREATE TABLE team (
  id TEXT NOT NULL PRIMARY KEY,
  name TEXT NOT NULL,
  time_zone TEXT NOT NULL
) WITHOUT ROWID;
CREATE UNIQUE INDEX team_name ON team (lower(name));

-- A Person's role in one Team over a date range. Ending a Membership sets `ended_at`; rows are
-- never deleted, so history stays. A role change ends one Membership and starts another.
CREATE TABLE membership (
  id TEXT NOT NULL PRIMARY KEY,
  team_id TEXT NOT NULL REFERENCES team (id),
  person_id TEXT NOT NULL REFERENCES person (id),
  role TEXT NOT NULL CHECK (role IN ('lead', 'member', 'viewer')),
  started_at INTEGER NOT NULL,
  ended_at INTEGER CHECK (ended_at IS NULL OR ended_at >= started_at)
) WITHOUT ROWID;
-- At most one active Membership per Person and Team.
CREATE UNIQUE INDEX membership_active ON membership (team_id, person_id) WHERE ended_at IS NULL;
CREATE INDEX membership_by_person ON membership (person_id);

import { SurveyBeatApi } from "@surveybeat/api";
import {
  type DirectoryCommand,
  type EmailAddress,
  type EmailOutbox,
  type Member,
  NewIds,
  type NewMember,
  type OrganizationDirectory,
  runDirectoryCommand,
  viewSettings,
  viewTeam,
  viewTeams,
} from "@surveybeat/domain";
import type * as Context from "effect/Context";
import * as Effect from "effect/Effect";
import * as HttpApiBuilder from "effect/http-api/HttpApiBuilder";
import { type AuthServices, currentMember, requestOrigin, requireSameOrigin } from "./auth/AuthHandlers.ts";

/** Everything the directory endpoints need: sign-in's services, the Organization objects, the email queue. */
export type DirectoryServices = AuthServices | OrganizationDirectory | EmailOutbox;

/**
 * The "Open SurveyBeat" link in the "You've been added" email: this app's front page. Always
 * https, which the email requires; only local workerd serves plain http.
 */
const signInUrl = Effect.map(requestOrigin, (origin) => {
  const url = new URL("/", origin);
  url.protocol = "https:";
  return url.toString();
});

const newMember = (email: EmailAddress) =>
  Effect.gen(function* () {
    const ids = yield* NewIds;
    return {
      email,
      personId: yield* ids.personId,
      membershipId: yield* ids.membershipId,
      signInUrl: yield* signInUrl,
    } satisfies NewMember;
  });

/** A change: same origin only, as the signed-in Person, then 204. */
const change = <R>(command: (member: Member) => Effect.Effect<DirectoryCommand, never, R>) =>
  Effect.gen(function* () {
    yield* requireSameOrigin;
    const member = yield* currentMember;
    yield* runDirectoryCommand(member, yield* command(member));
  });

/** The `directory` group of `SurveyBeatApi`: Teams, Leads, members, and Organization settings. */
export const directoryHandlers = <R>(
  services: Effect.Effect<Context.Context<DirectoryServices>, never, R>,
) => {
  const provide = <A, E, R2>(effect: Effect.Effect<A, E, R2>) =>
    Effect.flatMap(services, (context) => Effect.provideContext(effect, context));
  return HttpApiBuilder.group(SurveyBeatApi, "directory", (handlers) =>
    handlers
      .handle("listTeams", () => provide(Effect.flatMap(currentMember, viewTeams)))
      .handle("createTeam", ({ payload }) =>
        provide(
          Effect.gen(function* () {
            yield* requireSameOrigin;
            const member = yield* currentMember;
            const teamId = yield* (yield* NewIds).teamId;
            yield* runDirectoryCommand(member, {
              _tag: "CreateTeam",
              teamId,
              name: payload.name,
              timeZone: payload.timeZone,
              lead: yield* newMember(payload.leadEmail),
            });
            return yield* viewTeam(member, teamId);
          }),
        ),
      )
      .handle("getTeam", ({ params }) =>
        provide(Effect.flatMap(currentMember, (member) => viewTeam(member, params.teamId))),
      )
      .handle("updateTeam", ({ params, payload }) =>
        provide(
          change(() =>
            Effect.succeed({
              _tag: "UpdateTeam",
              teamId: params.teamId,
              name: payload.name,
              timeZone: payload.timeZone,
            }),
          ),
        ),
      )
      .handle("addMember", ({ params, payload }) =>
        provide(
          change(() =>
            Effect.map(newMember(payload.email), (member) => ({
              _tag: "AddMember",
              teamId: params.teamId,
              role: "member",
              member,
            })),
          ),
        ),
      )
      .handle("assignLead", ({ params, payload }) =>
        provide(
          change(() =>
            Effect.map(newMember(payload.email), (member) => ({
              _tag: "AddMember",
              teamId: params.teamId,
              role: "lead",
              member,
            })),
          ),
        ),
      )
      .handle("removeMember", ({ params }) =>
        provide(
          change(() =>
            Effect.succeed({ _tag: "RemoveMember", teamId: params.teamId, personId: params.personId }),
          ),
        ),
      )
      .handle("removeLead", ({ params }) =>
        provide(
          change(() =>
            Effect.flatMap(NewIds, (ids) => ids.membershipId).pipe(
              Effect.map((membershipId) => ({
                _tag: "RemoveLead",
                teamId: params.teamId,
                personId: params.personId,
                membershipId,
              })),
            ),
          ),
        ),
      )
      .handle("getSettings", () => provide(Effect.flatMap(currentMember, viewSettings)))
      .handle("updateSettings", ({ payload }) =>
        provide(
          change(() =>
            Effect.succeed({ _tag: "UpdateSettings", minimumGroupSize: payload.minimumGroupSize }),
          ),
        ),
      )
      .handle("grantAdmin", ({ params }) =>
        provide(
          change(() =>
            Effect.succeed({ _tag: "SetAdmin", personId: params.personId, organizationAdmin: true }),
          ),
        ),
      )
      .handle("revokeAdmin", ({ params }) =>
        provide(
          change(() =>
            Effect.succeed({ _tag: "SetAdmin", personId: params.personId, organizationAdmin: false }),
          ),
        ),
      )
      .handle("removePerson", ({ params }) =>
        provide(change(() => Effect.succeed({ _tag: "RemovePerson", personId: params.personId }))),
      ),
  );
};
import {
  AuthUnavailable,
  CreateOrganization,
  EmailAddress,
  Forbidden,
  LastAdmin,
  LastLead,
  MinimumGroupSize,
  Organization,
