  .prefix("/orgs") {}

/** The name a creator gives a new Organization: trimmed, 1 to 100 characters. */
export const OrganizationName = Schema.String.pipe(
  Schema.check(Schema.isTrimmed(), Schema.isMinLength(1), Schema.isMaxLength(100)),
);

/**
 * Sign-in (WorkOS AuthKit, SPEC §6.1). `login`, `callback`, and `logout` answer with redirects
 * and cookies, so browsers navigate to them; the app calls the other three.
 */
export class AuthApiGroup extends HttpApiGroup.make("auth")
  .add(
    HttpApiEndpoint.get("login", "/login", { success: HttpApiSchema.Empty(302) }),
    HttpApiEndpoint.get("callback", "/callback", {
      query: { code: Schema.optional(Schema.String), state: Schema.optional(Schema.String) },
      success: HttpApiSchema.Empty(302),
    }),
    HttpApiEndpoint.post("logout", "/logout", {
      success: HttpApiSchema.Empty(303),
      error: [Forbidden, AuthUnavailable],
    }),
    HttpApiEndpoint.get("session", "/session", {
      success: SessionState,
      error: [Unauthenticated, AuthUnavailable],
    }),
    HttpApiEndpoint.post("createOrganization", "/organization", {
      payload: Schema.Struct({ name: OrganizationName }),
      success: SessionState,
      error: [Unauthenticated, Forbidden, AuthUnavailable],
    }),
    HttpApiEndpoint.post("chooseOrganization", "/organization/choose", {
      payload: Schema.Struct({ organizationId: OrganizationId }),
      success: SessionState,
      error: [Unauthenticated, Forbidden, AuthUnavailable],
    }),
  )
  .prefix("/auth") {}

/**
 * Every directory call needs a session in an Organization (`Forbidden` also covers "not in one"),
 * and any of them may meet a rule. `AuthUnavailable`: WorkOS could not be reached; repeat the call.
 */
const directoryErrors = [
  Unauthenticated,
  Forbidden,
  AuthUnavailable,
  TeamNotFound,
  PersonNotFound,
  LastLead,
  LastAdmin,
  TeamNameTaken,
] as const;
const teamParams = { teamId: TeamId };
const memberParams = { teamId: TeamId, personId: PersonId };

/**
 * Teams, Leads, members, and Organization settings, for the signed-in Person's Organization
 * (never one named in the URL). The permission table in `@surveybeat/domain` decides each call
 * from the Organization's Durable Object. No endpoint returns Result data. Changes answer 204 and
 * the app reads the view again, since a change can end the caller's own access to it.
 */
export class DirectoryApiGroup extends HttpApiGroup.make("directory")
  .add(
    HttpApiEndpoint.get("listTeams", "/teams", {
      success: Schema.Array(TeamSummary),
      error: directoryErrors,
    }),
    HttpApiEndpoint.post("createTeam", "/teams", {
      payload: Schema.Struct({ name: TeamName, timeZone: TimeZone, leadEmail: EmailAddress }),
      success: TeamDetail,
      error: directoryErrors,
    }),
    HttpApiEndpoint.get("getTeam", "/teams/:teamId", {
      params: teamParams,
      success: TeamDetail,
      error: directoryErrors,
    }),
    HttpApiEndpoint.patch("updateTeam", "/teams/:teamId", {
      params: teamParams,
      payload: Schema.Struct({ name: TeamName, timeZone: TimeZone }),
      error: directoryErrors,
    }),
    HttpApiEndpoint.post("addMember", "/teams/:teamId/members", {
      params: teamParams,
      payload: Schema.Struct({ email: EmailAddress }),
      error: directoryErrors,
    }),
    HttpApiEndpoint.delete("removeMember", "/teams/:teamId/members/:personId", {
      params: memberParams,
      error: directoryErrors,
    }),
    HttpApiEndpoint.post("assignLead", "/teams/:teamId/leads", {
      params: teamParams,
      payload: Schema.Struct({ email: EmailAddress }),
      error: directoryErrors,
    }),
    HttpApiEndpoint.delete("removeLead", "/teams/:teamId/leads/:personId", {
      params: memberParams,
      error: directoryErrors,
    }),
    HttpApiEndpoint.get("getSettings", "/organization", {
      success: OrganizationSettings,
      error: directoryErrors,
    }),
    HttpApiEndpoint.patch("updateSettings", "/organization", {
      payload: Schema.Struct({ minimumGroupSize: MinimumGroupSize }),
      error: directoryErrors,
    }),
    HttpApiEndpoint.put("grantAdmin", "/organization/admins/:personId", {
      params: { personId: PersonId },
      error: directoryErrors,
    }),
    HttpApiEndpoint.delete("revokeAdmin", "/organization/admins/:personId", {
      params: { personId: PersonId },
      error: directoryErrors,
    }),
    HttpApiEndpoint.delete("removePerson", "/organization/people/:personId", {
      params: { personId: PersonId },
      error: directoryErrors,
    }),
  )
  .prefix("/api") {}

/** The HttpApi declaration shared by the server and the clients. */
export class SurveyBeatApi extends HttpApi.make("surveybeat")
  .add(OrganizationsApiGroup)
  .add(AuthApiGroup)
  .add(DirectoryApiGroup) {}
import type * as Arbitrary from "effect/Arbitrary";
import type { HttpApi, HttpApiGroup } from "effect/http-api";
import type { SurveyBeatApi } from "./index.ts";

/** `group.endpoint` for every endpoint of an HttpApi declaration. */
export type EndpointKey<Api> =
  Api extends HttpApi.HttpApi<infer _Id, infer Groups>
    ? Groups extends HttpApiGroup.Constraint
      ? `${Groups["identifier"]}.${HttpApiGroup.Endpoints<Groups>["identifier"]}`
      : never
    : never;

/**
 * Whether an endpoint's response can contain Result data (scores, distributions, comments, trends:
 * anything derived from Submissions). Those endpoints get an input generator that produces Rounds,
 * and a property test checks the minimum group size rules R1–R11 (ADR 0004) for each of them.
 */
export type EndpointPrivacy =
  | { readonly _tag: "NoResultData"; readonly why: string }
  | { readonly _tag: "ResultData"; readonly inputs: Arbitrary.Arbitrary<unknown> };

/**
 * Every endpoint of `SurveyBeatApi`, classified. A new endpoint does not typecheck until it is
 * listed here, and `registry.privacy.test.ts` checks the same against the runtime declaration.
 */
export const privacyRegistry: { readonly [K in EndpointKey<typeof SurveyBeatApi>]: EndpointPrivacy } = {
  "organizations.create": { _tag: "NoResultData", why: "returns the Organization's id and name" },
  "organizations.getById": { _tag: "NoResultData", why: "returns the Organization's id and name" },
  "auth.login": { _tag: "NoResultData", why: "redirects to the AuthKit hosted sign-in page" },
  "auth.callback": { _tag: "NoResultData", why: "sets the session cookie and redirects to the app" },
  "auth.logout": { _tag: "NoResultData", why: "clears the session cookie and redirects to WorkOS logout" },
  "auth.session": {
    _tag: "NoResultData",
    why: "returns the sign-in state: Organization ids and names, a Person id, and the admin flag",
  },
  "auth.createOrganization": {
    _tag: "NoResultData",
    why: "returns the sign-in state of the new Organization's admin",
  },
  "auth.chooseOrganization": {
    _tag: "NoResultData",
    why: "returns the sign-in state in the chosen Organization",
  },
  "directory.listTeams": {
    _tag: "NoResultData",
    why: "returns Team ids, names, time zones, and the caller's role",
  },
  "directory.createTeam": {
    _tag: "NoResultData",
    why: "returns the new Team's roster: emails, roles, start dates",
  },
  "directory.getTeam": {
    _tag: "NoResultData",
    why: "returns a Team's active roster (emails, roles, start dates) and what the caller may do",
  },
  "directory.updateTeam": {
    _tag: "NoResultData",
    why: "renames a Team or changes its time zone; no content",
  },
  "directory.addMember": { _tag: "NoResultData", why: "adds a member by email; no content" },
  "directory.removeMember": { _tag: "NoResultData", why: "ends a Membership; no content" },
  "directory.assignLead": { _tag: "NoResultData", why: "assigns a Lead by email; no content" },
  "directory.removeLead": { _tag: "NoResultData", why: "ends a Lead's lead Membership; no content" },
  "directory.getSettings": {
    _tag: "NoResultData",
    why: "returns the Organization's name, minimum group size, and People with their admin flag",
  },
  "directory.updateSettings": { _tag: "NoResultData", why: "sets the minimum group size; no content" },
  "directory.grantAdmin": { _tag: "NoResultData", why: "makes a Person an Organization admin; no content" },
  "directory.revokeAdmin": {
    _tag: "NoResultData",
    why: "ends a Person's Organization admin role; no content",
  },
  "directory.removePerson": {
    _tag: "NoResultData",
    why: "removes a Person from the Organization; no content",
  },
};
