        this.codes.delete(code);
        const organizations = [...this.memberships.keys()]
          .filter((key) => key.startsWith(`${userId}/`) && !this.inactiveMemberships.has(key))
          .map((key) => WorkosOrganizationId.make(key.slice(userId.length + 1)));
