202-  readonly organizationId: Effect.Effect<OrganizationId>;
203-  readonly personId: Effect.Effect<PersonId>;
204-  readonly teamId: Effect.Effect<TeamId>;
205-  readonly membershipId: Effect.Effect<MembershipId>;
206-}
