/** Teams, a Team, or the Organization settings, by the URL hash. */
function SignedIn({
  organization,
  organizationAdmin,
}: {
  readonly organization: string;
  readonly organizationAdmin: boolean;
}) {
  const route = useRoute();
  return (
    <Shell
      title={message("signedIn.title", { organization })}
      organizationAdmin={organizationAdmin}
      signOut={<SignOut />}
    >
      {route._tag === "Team" ? (
        <TeamScreen key={route.id} id={route.id} />
      ) : route._tag === "Settings" && organizationAdmin ? (
        <SettingsScreen />
      ) : (
        <TeamsScreen organizationAdmin={organizationAdmin} />
      )}
    </Shell>
  );
}

/** The app entry: the sign-in screens until a session is in an Organization. */
export function App() {
  const [view, setView] = useState<View | undefined>(undefined);
  useEffect(() => {
    void loadSession().then(setView);
  }, []);

  if (view === undefined) return <Screen title={message("app.loading")} />;
  switch (view._tag) {
    case "SignedOut":
      return <SignIn />;
    case "Failed":
      return (
        <Screen title={message("app.error")}>
          <Button className={`mt-4 ${buttonClass}`} onClick={() => void loadSession().then(setView)}>
            {message("app.retry")}
          </Button>
        </Screen>
      );
    case "CreateOrganization":
      return <CreateOrganization onDone={setView} />;
    case "NotInOrganization":
      return (
        <Screen title={message("notInOrganization.title")}>
          <p className="mt-2 text-gray-600">{message("notInOrganization.intro")}</p>
          <SignOut />
        </Screen>
      );
    case "ChooseOrganization":
      return <ChooseOrganization organizations={view.organizations} onDone={setView} />;
    case "SignedIn":
      return <SignedIn organization={view.organization.name} organizationAdmin={view.organizationAdmin} />;
  }
}
import { SurveyBeatApi } from "@surveybeat/api";
import { Effect, Predicate } from "effect";
import { FetchHttpClient } from "effect/http";
import { HttpApiClient } from "effect/http-api";

const client = HttpApiClient.make(SurveyBeatApi, { baseUrl: window.location.origin });
export type Client = Effect.Success<typeof client>;

/** Why a directory call failed, as the screens explain it. */
export type Failure =
  | "Unauthenticated"
  | "Forbidden"
  | "NotFound"
  | "LastLead"
  | "LastAdmin"
  | "TeamNameTaken"
  | "Invalid"
  | "Unavailable";

export type Outcome<A> =
  | { readonly ok: true; readonly value: A }
  | { readonly ok: false; readonly failure: Failure };

const failureOf = (error: unknown): Failure => {
  if (Predicate.isTagged(error, "Unauthenticated")) return "Unauthenticated";
  if (Predicate.isTagged(error, "Forbidden")) return "Forbidden";
  if (Predicate.isTagged(error, "TeamNotFound") || Predicate.isTagged(error, "PersonNotFound"))
    return "NotFound";
  if (Predicate.isTagged(error, "LastLead")) return "LastLead";
  if (Predicate.isTagged(error, "LastAdmin")) return "LastAdmin";
  if (Predicate.isTagged(error, "TeamNameTaken")) return "TeamNameTaken";
  if (Predicate.isTagged(error, "HttpApiSchemaError") || Predicate.isTagged(error, "SchemaError"))
    return "Invalid";
  return "Unavailable";
};

/** Runs one call of the `directory` group and reports its outcome; it never rejects. */
export const call = <A, E>(f: (api: Client["directory"]) => Effect.Effect<A, E>): Promise<Outcome<A>> =>
  Effect.runPromise(
    client.pipe(
      Effect.flatMap((api) => f(api.directory)),
      Effect.map((value): Outcome<A> => ({ ok: true, value })),
      Effect.catch((error: unknown) => Effect.succeed<Outcome<A>>({ ok: false, failure: failureOf(error) })),
      Effect.provide(FetchHttpClient.layer),
    ),
  );
